pub fn page_links(current: u32, total_pages: u32, radius: u32) -> Vec<PageLink> {
    if total_pages == 0 {
        return Vec::new();
    }
    let current = current.clamp(1, total_pages);
    let from = current.saturating_sub(radius).max(1);
    let to = (current + radius).min(total_pages);
    let mut links = Vec::new();
    if from > 1 {
        links.push(PageLink::Page(1));
        if from > 2 {
            links.push(PageLink::Gap);
        }
    }
    links.extend((from..=to).map(PageLink::Page));
    if to < total_pages {
        if to < total_pages - 1 {
            links.push(PageLink::Gap);
        }
        links.push(PageLink::Page(total_pages));
    }
    links
}

pub fn is_valid_card_number(input: &str) -> bool {
    let digits: Vec<u32> = input
        .chars()
        .filter(|c| !matches!(c, ' ' | '-'))
        .map(|c| c.to_digit(10))
        .collect::<Option<Vec<u32>>>()
        .unwrap_or_default();
    if !(12..=19).contains(&digits.len()) {
        return false;
    }
    let sum: u32 = digits
        .iter()
        .rev()
        .enumerate()
        .map(|(i, &d)| {
            if i % 2 == 1 {
                let doubled = d * 2;
                if doubled > 9 { doubled - 9 } else { doubled }
            } else {
                d
            }
        })
        .sum();
    sum % 10 == 0
}

pub fn cart_totals(lines: &[CartLine], coupon: Option<&Coupon>) -> Totals {
    let subtotal: i64 = lines
        .iter()
        .map(|line| line.unit_price_cents * i64::from(line.quantity))
        .sum();
    let discount = match coupon {
        Some(Coupon::Percent { percent }) => subtotal * i64::from((*percent).min(100)) / 100,
        Some(Coupon::Fixed { amount_cents }) => (*amount_cents).clamp(0, subtotal),
        None => 0,
    };
    let taxable = subtotal - discount;
    let tax = (taxable * TAX_RATE_PERCENT + 50) / 100;
    let shipping = if lines.is_empty() || taxable >= FREE_SHIPPING_FROM {
        0
    } else {
        SHIPPING_FEE
    };
    Totals {
        subtotal,
        discount,
        tax,
        shipping,
        total: taxable + tax + shipping,
    }
}

pub fn excerpt(body: &str, max_words: usize) -> String {
    let words: Vec<&str> = body.split_whitespace().collect();
    if words.len() <= max_words {
        return words.join(" ");
    }
    let mut cut = words[..max_words].join(" ");
    while cut.ends_with(|c: char| matches!(c, ',' | ';' | ':' | '.' | '-')) {
        cut.pop();
    }
    cut.push('…');
    cut
}

pub fn relative_time(then: DateTime<Utc>, now: DateTime<Utc>) -> String {
    let seconds = (now - then).num_seconds().max(0);
    let minutes = seconds / 60;
    let hours = minutes / 60;
    let days = hours / 24;
    match () {
        _ if seconds < 45 => "just now".to_string(),
        _ if minutes < 60 => plural(minutes.max(1), "minute"),
        _ if hours < 24 => plural(hours, "hour"),
        _ if days == 1 => "yesterday".to_string(),
        _ if days < 7 => plural(days, "day"),
        _ if days < 30 => plural(days / 7, "week"),
        _ if days < 365 => plural(days / 30, "month"),
        _ => plural(days / 365, "year"),
    }
}

pub fn validate_email(input: &str) -> Result<(), FieldError> {
    let email = input.trim();
    if email.is_empty() {
        return Err(FieldError::new("email", "Email is required"));
    }
    if email.len() > MAX_EMAIL_LEN {
        return Err(FieldError::new("email", "Email is too long"));
    }
    let Some((local, domain)) = email.split_once('@') else {
        return Err(FieldError::new("email", "Email must contain @"));
    };
    if local.is_empty() || local.len() > MAX_LOCAL_PART_LEN || domain.contains('@') {
        return Err(FieldError::new("email", "Email address is invalid"));
    }
    let labels: Vec<&str> = domain.split('.').collect();
    let domain_ok = labels.len() >= 2
        && labels.iter().all(|label| {
            !label.is_empty()
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
        });
    if !domain_ok {
        return Err(FieldError::new("email", "Email domain is invalid"));
    }
    Ok(())
}

pub fn password_strength(password: &str) -> Strength {
    if COMMON_PASSWORDS.contains(&password.to_lowercase().as_str()) {
        return Strength::Weak;
    }
    let mut score = 0;
    if password.chars().count() >= 8 {
        score += 1;
    }
    if password.chars().count() >= 12 {
        score += 1;
    }
    if password.chars().any(|c| c.is_lowercase()) && password.chars().any(|c| c.is_uppercase()) {
        score += 1;
    }
    if password.chars().any(|c| c.is_ascii_digit()) {
        score += 1;
    }
    if password.chars().any(|c| !c.is_alphanumeric()) {
        score += 1;
    }
    match score {
        0..=2 => Strength::Weak,
        3 => Strength::Fair,
        _ => Strength::Strong,
    }
}

function checkEmail(value: string): string | null {
  const address = value.trim();
  if (address === '') return 'Please enter your email';
  if (address.length > MAX_EMAIL_LENGTH) return 'That email is too long';
  const at = address.indexOf('@');
  if (at <= 0 || at !== address.lastIndexOf('@') || at > 64) {
    return 'That does not look like an email address';
  }
  const domainParts = address.slice(at + 1).split('.');
  const goodDomain =
    domainParts.length > 1 &&
    domainParts.every((part) => /^[a-z0-9]+(-[a-z0-9]+)*$/i.test(part));
  return goodDomain ? null : 'Check the part after @';
}
